package learn

// The term tables of the learn-side withholding classifier. A term is written
// as plain words; the matcher folds both sides alike (case, accents, width and
// punctuation). A leading "=" makes a term a whole word, a trailing "*" lets
// its last word continue, and otherwise a last word of five or more letters
// continues. A leading "^" makes a term the whole label: the question holds
// nothing beside it, as an expiry date is a card's only when nothing says
// what expires. Terms in Chinese, Japanese and Korean are escaped, since the
// repository keeps its source in ASCII and Latin letters, and are matched as
// substrings of the question with its spaces removed.

// languages lists the languages every term group covers; a test fails for a
// group that misses one.
var languages = []string{"en", "de", "fr", "es", "pt", "it", "nl", "zh", "ja", "ko", "pl", "sv", "ru", "ar", "hi", "da", "no", "fi", "tr"}

// termGroup is the vocabulary of one withheld category in every language.
type termGroup struct {
	withheld Withheld
	// sub names the self-identification kind; empty for the other categories.
	sub   string
	terms map[string][]string
}

